<?php require __DIR__.'/includes/bootstrap.php';global $animals,$ongs;$selected=(int)($_GET['animal']??0);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$animalId=(int)$_POST['animal_id'];$a=find_animal($animalId);if($a){add_store('adocoes',['animal_id'=>$animalId,'animal'=>$a['nome'],'nome'=>trim($_POST['nome']),'email'=>trim($_POST['email']),'telefone'=>trim($_POST['telefone']),'cidade'=>trim($_POST['cidade']),'moradia'=>trim($_POST['moradia']),'mensagem'=>trim($_POST['mensagem'])]);flash('ok','Recebemos seu interesse. A ONG responsável entra em contato para conversar.');redirect('animal.php?id='.$animalId);}}$pageTitle='Adoção';require __DIR__.'/includes/header.php';$list=array_filter($animals,fn($a)=>$a['status']==='Disponível');$focus=$selected?$animals[$selected]??null:null; ?><section class="page-hero"><div class="container"><span class="eyebrow">Adoção responsável</span><h1>Não é escolher um animal. É escolher uma rotina junto.</h1><p>Por isso cada perfil mostra mais do que uma foto: idade, porte, comportamento, onde foi encontrado e quem acompanha o caso.</p></div></section><section class="section-tight"><div class="container"><div class="filters"><button class="filter active" data-filter="todos">Todos</button><button class="filter" data-filter="Cão">Cães</button><button class="filter" data-filter="Gato">Gatos</button></div><div class="cards"><?php foreach($list as $id=>$a):?><article class="animal-card" data-item="<?=e($a['especie'])?>"><a href="animal.php?id=<?=$id?>"><div class="card-photo" style="background-image:url('<?=e($a['foto'])?>')"></div><div class="card-body"><span class="chip"><?=e($a['status'])?></span><h3><?=e($a['nome'])?></h3><div class="meta"><span><?=e($a['idade'])?></span><span>·</span><span><?=e($a['porte'])?></span><span>·</span><span><?=e($a['sexo'])?></span></div><p><?=e($a['temperamento'])?></p><div class="card-bottom"><span class="text-link">Ler perfil →</span><span class="meta"><?=e($ongs[$a['ong']]['nome'])?></span></div></div></a></article><?php endforeach;?></div></div></section><?php if($selected&&$focus): ?><section class="section section-soft"><div class="container form-shell"><span class="eyebrow">Interesse em <?=e($focus['nome'])?></span><h2 style="margin-top:8px">Vamos começar a conversa.</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="animal_id" value="<?=$selected?>"><div class="form-grid"><div class="field"><label>Seu nome</label><input name="nome" required></div><div class="field"><label>E-mail</label><input type="email" name="email" required></div><div class="field"><label>Telefone</label><input name="telefone" required></div><div class="field"><label>Cidade</label><input name="cidade" required></div><div class="field"><label>Onde o animal ficaria?</label><select name="moradia"><option>Casa com quintal</option><option>Casa sem quintal</option><option>Apartamento</option></select></div><div class="field"><label>Você já teve animais?</label><select name="experiencia"><option>Sim</option><option>Não</option><option>Tenho outros animais hoje</option></select></div><div class="field full"><label>Conte um pouco sobre sua rotina</label><textarea name="mensagem" placeholder="Ex.: fico fora durante o dia, tenho crianças, outros animais..."></textarea></div></div><label class="check"><input type="checkbox" required> Entendo que este formulário é apenas uma manifestação de interesse e que a adoção depende da avaliação da ONG.</label><button class="btn btn-dark">Enviar interesse</button></form></div></section><?php endif; ?><?php require __DIR__.'/includes/footer.php'; ?>
